-- =====================================================================================
-- Fief WoD : contenu des batiments (bug « couture vide ») + quete 34461 « Construire votre caserne »
-- Joueur : Wissmerill (guid 339). PARTIE B : a appliquer AVEC le nouveau binaire (contenu des batiments,
-- critere 169, caserne de quete), sinon les casernes deja construites perdent leur contenu.
-- (sans lui, les deux tables ci-dessous ne sont lues par personne).
-- A deposer dans sql/updates/world/master/ (DBUpdater) ; worldserver arrete.
-- =====================================================================================

-- 1) Tables de LegionCore (schema de lc_world_ref, AUTO_INCREMENT repart de 1)
--    Source des lignes : lc_world_ref.garrison_building_creature (792) / garrison_building_gameobject (828),
--    hors 48 lignes dont les 25 gabarits d objets manquent chez nous (liste au bloc 1b).
--    Colonne `building` = 1 : ouvriers du chantier ; rotation0-3 = rotation PARENTE (celle de la parcelle).
--    NON repris : sql/updates/world/2026_10_22_87_garrison_construction_workers.sql de LC
--    (coordonnees a 2 decimales posees a la main, aucune source).
DROP TABLE IF EXISTS `garrison_building_creature`;
CREATE TABLE `garrison_building_creature` (
  `plotID` mediumint(8) unsigned NOT NULL,
  `BuildID` mediumint(8) unsigned NOT NULL,
  `id` mediumint(8) unsigned NOT NULL DEFAULT 0 COMMENT 'Creature Identifier',
  `map` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'Map Identifier',
  `position_x` float NOT NULL DEFAULT 0,
  `position_y` float NOT NULL DEFAULT 0,
  `position_z` float NOT NULL DEFAULT 0,
  `orientation` float NOT NULL DEFAULT 0,
  `building` smallint(1) unsigned NOT NULL DEFAULT 0,
  `idx` int(11) NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`idx`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COMMENT='Garrison building spawn System (LegionCore)';

DROP TABLE IF EXISTS `garrison_building_gameobject`;
CREATE TABLE `garrison_building_gameobject` (
  `plotID` mediumint(8) unsigned NOT NULL,
  `BuildID` mediumint(8) unsigned NOT NULL,
  `id` mediumint(8) unsigned NOT NULL DEFAULT 0 COMMENT 'Gameobject Identifier',
  `map` smallint(5) unsigned NOT NULL DEFAULT 0 COMMENT 'Map Identifier',
  `position_x` float NOT NULL DEFAULT 0,
  `position_y` float NOT NULL DEFAULT 0,
  `position_z` float NOT NULL DEFAULT 0,
  `orientation` float NOT NULL DEFAULT 0,
  `rotation0` float NOT NULL DEFAULT 0,
  `rotation1` float NOT NULL DEFAULT 0,
  `rotation2` float NOT NULL DEFAULT 0,
  `rotation3` float NOT NULL DEFAULT 0,
  `building` tinyint(1) unsigned NOT NULL DEFAULT 0,
  `idx` int(11) NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`idx`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3 COMMENT='Garrison building spawn System (LegionCore)';

-- 1a) 792 PNJ

-- 1b) 780 objets (48 lignes ecartees : gabarits absents chez nous : 227796, 228618, 228665, 228689, 231905, 233727, 233729, 233730, 234579, 237124, 237125, 237126, 237178, 237179, 237182, 237411, 237412, 237413, 237414, 237438, 238811, 238812, 238813, 238814, 239262)

-- 2) Fief Horde niveau 1 (carte 1152) : la caserne « construite d'office »
--    Ce sont des apparitions STATIQUES (phase 0, donc vues par tous) issues d'un relevé fait chez un joueur
--    qui avait deja sa caserne : le batiment 230412 « Garrison Building Horde Barracks V1 » pose sur la
--    parcelle 23, plus son contenu (gameobject_addon.parent_rotation = rotation de la parcelle 23, 0,4617/0,8870).
--    LegionCore n'a aucune de ces apparitions : ce contenu est chez lui dans garrison_building_* (BuildID 26,
--    plotID 23, carte 1152 : memes entrees aux memes coordonnees, verifie a < 1 m).
DELETE FROM `gameobject`       WHERE `guid` = 1461466 AND `id` = 230412 AND `map` = 1152;
DELETE FROM `gameobject_addon` WHERE `guid` = 1461466;
DELETE FROM `gameobject`       WHERE `map` = 1152 AND `guid` IN (1461475,1461482,1461483,1461484,1461485,1461488,1461489,1461492,1461494);
DELETE FROM `gameobject_addon` WHERE `guid` IN (1461475,1461482,1461483,1461484,1461485,1461488,1461489,1461492,1461494);
DELETE FROM `creature`         WHERE `map` = 1152 AND `guid` IN (10175351,10175364,10175367,10175373,10175375,10175376,10175378,10175384,10175387);

-- 2b) OPTIONNEL (non sourcé) : objet statique « Small Plot » 233083 pose sur la parcelle 18, en double de celui
--     que le core cree lui-meme (GameObjects.db2) ; chez Wissmerill il se trouve DANS sa couturerie.
--     LegionCore garde le sien (guid 129555) : decision a prendre, d'ou la mise en commentaire.
DELETE FROM `gameobject` WHERE `guid` = 1461464 AND `id` = 233083 AND `map` = 1152;
DELETE FROM `gameobject_addon` WHERE `guid` = 1461464;

-- 2c) OPTIONNEL : meme pollution sur les autres cartes de fief (apparitions statiques identiques, a < 1 m,
