DELETE FROM `creature` WHERE `map` = 1159 AND `guid` IN (10656230,10656279,10656299,10656305,10656332,10656335,10656374,10656725);
DELETE FROM `creature` WHERE `map` = 1331 AND `guid` IN (10517913,10517955,10517958,10517991);
