-- 3) Quete 34461 (Horde) / 34587 (Alliance), objectif « Trouvez les plans » : l'objet « Garrison Blueprint: Barracks »
--    n'a AUCUNE apparition chez nous (ni 231012 Horde, ni 231855 Alliance). Le critere 25822 (type 36, objet 111956
--    « Barracks, Level 1 », butin 100 % de ces coffres) est donc inatteignable et le plan 26 ne peut etre appris.
-- 3a) Alliance : apparition de LegionCore (lc_world_ref.gameobject guid 133282), recopiee telle quelle
--     (sa PhaseId LC est une liste de 18 phases : ramenee a 0 comme le reste du fief Alliance).
DELETE FROM `gameobject` WHERE `guid` = 290400407;
-- 3b) Horde : AUCUNE source n'a d'apparition (ni LC, ni nos bases). Position tiree des pins Wowhead de l'objet 231012
--     (zone 7004, grappe 59,3-59,5 / 49,4-49,8), convertis par WorldMapArea.db2 (7004 : 4885,4/4183,3/5814,6/5345,8)
--     puis recales sur Gazlowe et Warmaster Zog (biais mesure -4,4 / -0,8 m). Precision ~5 m, au milieu de la
--     parcelle 23. Z = scripts/mapheight.py sur 1152 (130,37 = Z de la parcelle). Orientation inconnue : 0.
--     Meme methode verifiee sur l'apparition Alliance de LC (ecart 7,7 m sans recalage).
DELETE FROM `gameobject` WHERE `guid` = 290400406;

